cd /private/tmp/vista-task002-local-3x3-20260823-11/formal-task002-local-3x3-minimaxm3-20260823-11-retry-external-native-replicate-03/workspace && python3 -c "
import json
with open('DATA/products/CoachForce.json') as f:
    data = json.load(f)
# Find slack messages about market research report with replies
for s in data['slack']:
    msg_obj = s.get('Message', {})
    if isinstance(msg_obj, dict):
        user_obj = msg_obj.get('User', {})
        text = user_obj.get('text', '') if isinstance(user_obj, dict) else ''
        sender = user_obj.get('userId', '') if isinstance(user_obj, dict) else ''
    else:
        text, sender = str(msg_obj), ''
    thread = s.get('ThreadReplies', [])
    if 'final_cofoaix_market_research_report' in text or 'cofoaix_market_research_report' in text:
        print(f\"id={s['id']} Channel={s.get('Channel', {}).get('name')} Sender={sender}\")
        print(f\"  Message: {text}\")
        for r in thread:
            if isinstance(r, dict):
                u = r.get('User', {})
                if isinstance(u, dict):
                    print(f\"  Reply from {u.get('userId')}: {u.get('text', '')[:300]}\")
            else:
                print(f\"  Reply: {r}\")
        print()
"

